function draw({board,width,height,params}) {
 const p=VisualBook.palette, mobile=width<600;
 const f=n=>Number(n).toFixed(2);
 function panels(){
   if(mobile) return [[48,64,width-22,184],[48,332,width-22,458]];
   return [[50,64,width/2-26,height-108],[width/2+48,64,width-22,height-108]];
 }
 function heading(id,text,box){board.text(id,text,box[0],box[1]-28,{size:14,color:p.ink,weight:600});}
 function dot(id,frame,x,y,color,r=4){board.circle(id,frame.x(x),frame.y(y),r,color);}
 function guide(id,frame,x,y,color){board.line(id,frame.x(x),frame.y(0),frame.x(x),frame.y(y),color,1,0.35);}

 const data=[[-2,-1],[-1,0.2],[0,1.4],[1,1.6],[2,3.2]], w=params.w,b=1;
 const predictions=data.map(([x])=>w*x+b), residuals=data.map((d,i)=>predictions[i]-d[1]);
 const loss=residuals.reduce((s,r)=>s+r*r,0)/(2*data.length);
 const lossAt=v=>data.reduce((s,[x,y])=>s+(v*x+b-y)**2,0)/(2*data.length);
 const optimum=data.reduce((s,[x,y])=>s+x*(y-b),0)/data.reduce((s,[x])=>s+x*x,0);
 const [A,B]=panels();
 heading('head-data','样本空间 · 标签 y',A); heading('head-loss','参数空间 · 平均损失 L',B);
 const a=board.axes('samples',{xDomain:[-2.3,2.3],yDomain:[-4,6],box:A,xLabel:'特征 x',yLabel:'',grid:false});
 const z=board.axes('landscape',{xDomain:[0,2],yDomain:[0,1.2],box:B,xLabel:'权重 w',yLabel:'',grid:false});
 board.curve('model',a,[[-2.3,w*(-2.3)+b],[2.3,w*2.3+b]],{color:p.blue,width:2.5});
 data.forEach(([x,y],i)=>{
   board.line('residual-'+i,a.x(x),a.y(y),a.x(x),a.y(predictions[i]),p.orange,2);
   dot('obs-'+i,a,x,y,p.ink,4);
   board.mark('prediction-'+i,'circle',{cx:a.x(x),cy:a.y(predictions[i]),r:3.5,fill:p.paper,stroke:p.blue,'stroke-width':1.8});
 });
 const curve=Array.from({length:101},(_,i)=>[i/50,lossAt(i/50)]);
 board.curve('loss-curve',z,curve,{color:p.orange,width:2.4});
 board.mark('optimum-guide','line',{x1:z.x(optimum),x2:z.x(optimum),y1:z.y(0),y2:z.y(1.2),stroke:p.muted,'stroke-width':1,'stroke-dasharray':'3 5',opacity:0.45});
 guide('current-guide',z,w,loss,p.blue); dot('current',z,w,loss,p.blue,5.5);
 board.text('legend','● 观测   ○ 预测   │ 残差',A[0],A[3]+68,{size:12,color:p.muted});
 board.text('readout','w = '+f(w)+'   L = '+f(loss),B[0],B[3]+68,{size:14,color:p.blue,weight:600});
 board.text('slice-min','虚线：此切片最小点 w = '+f(optimum),B[0],B[3]+90,{size:12,color:p.muted});
 return {data,weight:w,bias:b,predictions,residuals,loss,optimumWeight:optimum,optimumLoss:lossAt(optimum)};
}

function draw({board,width,height,progress,params}) {
 const p=VisualBook.palette, mobile=width<600;
 const f=n=>Number(n).toFixed(2);
 function panels(){
   if(mobile) return [[48,64,width-22,184],[48,332,width-22,458]];
   return [[50,64,width/2-26,height-108],[width/2+48,64,width-22,height-108]];
 }
 function heading(id,text,box){board.text(id,text,box[0],box[1]-28,{size:14,color:p.ink,weight:600});}
 function dot(id,frame,x,y,color,r=4){board.circle(id,frame.x(x),frame.y(y),r,color);}
 function guide(id,frame,x,y,color){board.line(id,frame.x(x),frame.y(0),frame.x(x),frame.y(y),color,1,0.35);}

 const data=[[-1,0],[1,2],[2,3]],start=[0.2,0.5], eta=params.eta;
 const residuals=data.map(([x,y])=>start[0]*x+start[1]-y);
 const terms=data.map(([x],i)=>[x*residuals[i],residuals[i]]);
 const gradient=[0,1].map(k=>terms.reduce((s,t)=>s+t[k],0)/3);
 const end=start.map((v,k)=>v-eta*gradient[k]);
 const theta=start.map((v,k)=>v+progress*(end[k]-v));
 const L=t=>data.reduce((s,[x,y])=>s+(t[0]*x+t[1]-y)**2,0)/6;
 const [A,B]=panels();
 heading('head-contribution','更新前 · 每个样本的贡献',A);
 heading('head-model','一次更新 · 标签 y',B);
 const a={left:A[0],right:A[2],top:A[1],bottom:A[3],x:v=>A[0]+(v-0.5)/3*(A[2]-A[0]),y:v=>A[3]-(v+4.8)/5.8*(A[3]-A[1])};
 board.line('bar-y-axis',a.left,a.top,a.left,a.bottom,p.muted,1);
 board.line('bar-zero',a.left,a.y(0),a.right,a.y(0),p.muted,1,0.45);
 [-4,-2,0].forEach(v=>board.text('bar-y-'+v,String(v),a.left-9,a.y(v)+4,{size:12,color:p.muted,anchor:'end'}));
 data.forEach(([x],i)=>board.text('sample-x-'+i,'x = '+x,a.x(i+1),a.bottom+24,{size:12,color:p.muted,anchor:'middle'}));
 board.text('bar-axis-name','梯度贡献',a.right,a.bottom+48,{size:13,color:p.ink,anchor:'end'});
 const z=board.axes('fit',{xDomain:[-1.4,2.4],yDomain:[-1.5,6.5],box:B,xLabel:'特征 x',yLabel:'',grid:false});
 terms.forEach((t,i)=>{
   const x=i+1;
   [1,0].forEach((k,j)=>{
     const xx=a.x(x+(j===0?-0.2:0.2)), y=a.y(t[k]), base=a.y(0), color=k===1?p.orange:p.blue;
     board.rect('bar-'+i+'-'+k,xx-6,Math.min(y,base),12,Math.max(1,Math.abs(y-base)),color,{opacity:0.8});
     board.text('term-'+i+'-'+k,f(t[k]),xx,y+(t[k]<0?16:-8),{size:12,color,anchor:'middle'});
   });
 });
 board.curve('old-model',z,[[-1.4,start[0]*-1.4+start[1]],[2.4,start[0]*2.4+start[1]]],{color:p.muted,width:1.5,opacity:0.45});
 board.curve('new-model',z,[[-1.4,theta[0]*-1.4+theta[1]],[2.4,theta[0]*2.4+theta[1]]],{color:p.blue,width:2.5});
 data.forEach(([x,y],i)=>dot('data-'+i,z,x,y,p.ink,4));
 board.text('gradients','均值：g_b = '+f(gradient[1])+'   g_w = '+f(gradient[0]),A[0],A[3]+68,{size:13,color:p.ink});
 board.text('bar-legend','橙 r → 偏置；蓝 xr → 权重',A[0],A[3]+90,{size:12,color:p.muted});
 board.text('theta','w = '+f(theta[0])+'   b = '+f(theta[1])+'   L = '+f(L(theta)),B[0],B[3]+68,{size:13,color:p.blue,weight:600});
 board.text('loss-change','本批 L：'+f(L(start))+' → '+f(L(end))+(L(end)>L(start)?'  上升':'  下降'),B[0],B[3]+90,{size:12,color:L(end)>L(start)?p.orange:p.muted});
 return {data,start,residuals,terms,gradient,eta,end,current:theta,progress,startLoss:L(start),endLoss:L(end),currentLoss:L(theta),interpolationOnly:true};
}

function draw({board,width,height,params}) {
 const p=VisualBook.palette, mobile=width<600;
 const f=n=>Number(n).toFixed(2);
 function panels(){
   if(mobile) return [[48,64,width-22,184],[48,332,width-22,458]];
   return [[50,64,width/2-26,height-108],[width/2+48,64,width-22,height-108]];
 }
 function heading(id,text,box){board.text(id,text,box[0],box[1]-28,{size:14,color:p.ink,weight:600});}
 function dot(id,frame,x,y,color,r=4){board.circle(id,frame.x(x),frame.y(y),r,color);}
 function guide(id,frame,x,y,color){board.line(id,frame.x(x),frame.y(0),frame.x(x),frame.y(y),color,1,0.35);}

 const data=[[-2,-1],[-1,0],[0,1],[1,2],[2,4]], b=params.b,sigma=params.sigma,n=data.length;
 const lossAt=t=>data.reduce((s,[x,y])=>s+(x+t-y)**2,0)/(2*n);
 const constant=n/2*Math.log(2*Math.PI*sigma*sigma),scale=n/(sigma*sigma);
 const nllAt=t=>constant+scale*lossAt(t), optimum=data.reduce((s,[x,y])=>s+y-x,0)/n;
 const [A,B]=panels();
 heading('head-square','平方损失 L · 固定 w = 1',A); heading('head-nll','负对数似然 NLL',B);
 const a=board.axes('square',{xDomain:[-1,3],yDomain:[0,2.8],box:A,xLabel:'偏置 b',yLabel:'',grid:false});
 const z=board.axes('nll',{xDomain:[-1,3],yDomain:[0,40],box:B,xLabel:'偏置 b',yLabel:'',grid:false});
 [[a,lossAt,'loss',p.blue],[z,nllAt,'likelihood',p.orange]].forEach(([axis,fn,id,color])=>{
   board.curve(id+'-curve',axis,Array.from({length:121},(_,i)=>{const t=-1+i/30;return [t,fn(t)];}),{color,width:2.4});
   board.mark(id+'-minimum','line',{x1:axis.x(optimum),x2:axis.x(optimum),y1:axis.top,y2:axis.bottom,stroke:p.muted,'stroke-width':1,'stroke-dasharray':'3 5',opacity:0.5});
   guide(id+'-current-guide',axis,b,fn(b),color); dot(id+'-current',axis,b,fn(b),color,5.5);
 });
 board.text('loss-number','b = '+f(b)+'   L = '+f(lossAt(b)),A[0],A[3]+68,{size:14,color:p.blue,weight:600});
 board.text('same-min','虚线：同一最小点 b = '+f(optimum),A[0],A[3]+90,{size:12,color:p.muted});
 board.text('nll-number','NLL = '+f(nllAt(b)),B[0],B[3]+68,{size:14,color:p.orange,weight:600});
 board.text('scale','常数 '+f(constant)+'  +  '+f(scale)+' × L',B[0],B[3]+90,{size:12,color:p.muted});
 return {data,weight:1,bias:b,sigma,loss:lossAt(b),nll:nllAt(b),constant,scale,optimumBias:optimum,minimumLoss:lossAt(optimum),minimumNll:nllAt(optimum),fixedSigmaAcrossSamples:true};
}
